ALTER TABLE Outbox ADD Version BIGINT NOT NULL DEFAULT 1,Attempts BIGINT NOT NULL DEFAULT 0,CycleAttempts BIGINT NOT NULL DEFAULT 0,
    NextAttemptAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2,LeaseToken NVARCHAR(100) COLLATE Latin1_General_100_BIN2,LeaseUntil NVARCHAR(40) COLLATE Latin1_General_100_BIN2,
    LastCode NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT '',Receipt NVARCHAR(2000) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT '',UpdatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT '';
UPDATE Outbox SET UpdatedAt=CreatedAt,NextAttemptAt=CreatedAt;
CREATE INDEX IX_Outbox_Due ON Outbox(State,NextAttemptAt,CreatedAt);
CREATE TABLE OutboxAttempts(LeaseToken NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY,TaskId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES Outbox(Id),Attempt BIGINT NOT NULL,
    Outcome NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,StartedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL,FinishedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2);
CREATE INDEX IX_OutboxAttempts_Task ON OutboxAttempts(TaskId,StartedAt);
CREATE TABLE TaskActions(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY,TaskId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES Outbox(Id),Actor NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,Reason NVARCHAR(500) COLLATE Latin1_General_100_BIN2 NOT NULL,CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL);
CREATE INDEX IX_TaskActions_Task ON TaskActions(TaskId,CreatedAt);
